#include "test_harness.h"
#include "cheat/cheat_crypto.h"

/* Known-answer vectors generated by running mGBA's own routines
 * (src/gba/cheats/gameshark.c GBACheatEncryptGameShark and codebreaker.c
 * _cbReseed/_cbDecrypt, mgba-emu/mgba master, 2026-10-10) in a scratch
 * harness outside this repo. The implementation under test was written from
 * GBATEK "GBA Cheat Devices" pseudocode only, so agreement ties two
 * independent sources. */

static const uint32_t k_gsa[][4] = {   /* raw a, raw v, encrypted a, encrypted v */
    {0x0202BC24U, 0x000000FFU, 0xCF093F3EU, 0x3ED06CC1U},
    {0x1202BC24U, 0x0000FFFFU, 0xFB8F637DU, 0xB4564BF8U},
    {0x2202BC24U, 0x12345678U, 0xF745955BU, 0x1C51BF0AU},
    {0xD2025838U, 0x000003E7U, 0x47217C3AU, 0x88E08013U},
    {0x0864A1B0U, 0x001DC0DEU, 0x79708EA6U, 0xBA6EAAC4U},
};

static const uint32_t k_par3[][4] = {
    {0x00224ABCU, 0x00000063U, 0xC9FCEF03U, 0x7A820238U},
    {0x02224ABCU, 0x0000270FU, 0x6F869DB4U, 0x54D227F8U},
    {0x04224ABCU, 0x0098967FU, 0x70B90BC5U, 0x95DB3F60U},
    {0x4A224ABCU, 0x00000001U, 0x7A322843U, 0x8887EFA3U},
    {0x45424D50U, 0x001DC0DEU, 0xEC2C5E7AU, 0xEF0C11B5U},
};

/* key a, key v, encrypted a, encrypted v, decrypted a, decrypted v */
static const uint32_t k_cb[][6] = {
    {0x9123A0B5U, 0x1E3CU, 0x82025838U, 0x03E7U, 0xD1F9673FU, 0xDD16U},
    {0x9123A0B5U, 0x1E3CU, 0x3A1B2C3DU, 0x4E5FU, 0xEC7B232DU, 0xEEA4U},
    {0x9123A0B5U, 0x1E3CU, 0xDEADBEEFU, 0x0123U, 0x2B6E4373U, 0x0009U},
    {0x9A0F00FFU, 0xC4D2U, 0x82025838U, 0x03E7U, 0x0AD2DDFEU, 0x23F8U},
    {0x9A0F00FFU, 0xC4D2U, 0x3A1B2C3DU, 0x4E5FU, 0x33220B9DU, 0xD4C2U},
    {0x9A0F00FFU, 0xC4D2U, 0xDEADBEEFU, 0x0123U, 0x3FE1659FU, 0x706EU},
};

TEST(cheat_tea_gsa_matches_reference) {
    for (size_t i = 0; i < sizeof(k_gsa) / sizeof(k_gsa[0]); i++) {
        uint32_t a = k_gsa[i][0], v = k_gsa[i][1];
        cheat_tea_encrypt(&a, &v, CHEAT_SEEDS_GSA);
        ASSERT_EQ_HEX(a, k_gsa[i][2]);
        ASSERT_EQ_HEX(v, k_gsa[i][3]);
        cheat_tea_decrypt(&a, &v, CHEAT_SEEDS_GSA);
        ASSERT_EQ_HEX(a, k_gsa[i][0]);
        ASSERT_EQ_HEX(v, k_gsa[i][1]);
    }
}

TEST(cheat_tea_par3_matches_reference) {
    for (size_t i = 0; i < sizeof(k_par3) / sizeof(k_par3[0]); i++) {
        uint32_t a = k_par3[i][2], v = k_par3[i][3];
        cheat_tea_decrypt(&a, &v, CHEAT_SEEDS_PAR3);
        ASSERT_EQ_HEX(a, k_par3[i][0]);
        ASSERT_EQ_HEX(v, k_par3[i][1]);
    }
}

TEST(cheat_cb_reseed_matches_reference) {
    static const uint8_t table[48] = {19, 41, 13, 24, 29, 8,  6,  38, 11, 34, 32, 46, 17, 9,  14, 36,
                                      15, 47, 44, 26, 10, 25, 23, 2,  33, 12, 16, 4,  3,  31, 5,  1,
                                      37, 35, 22, 39, 0,  18, 45, 27, 28, 7,  42, 20, 40, 30, 43, 21};
    CbCrypt cb;
    cheat_cb_reseed(&cb, 0x9123A0B5U, 0x1E3C);
    /* mGBA keeps these as seeds[0..3]; GBATEK packs them into seedlist:
     * +2 word = seeds[2], +6 halfword = seeds[3], +8 word = seeds[0], +12 halfword = seeds[1]. */
    const uint8_t* sl = cb.seedlist;
    ASSERT_EQ_HEX(sl[0] | (sl[1] << 8), 0xA0B5U);   /* low half of the key's address */
    ASSERT_EQ_HEX(sl[2] | (sl[3] << 8) | ((uint32_t)sl[4] << 16) | ((uint32_t)sl[5] << 24), 0xA63929E9U);
    ASSERT_EQ_HEX(sl[6] | (sl[7] << 8), 0xF7E8U);
    ASSERT_EQ_HEX(sl[8] | (sl[9] << 8) | ((uint32_t)sl[10] << 16) | ((uint32_t)sl[11] << 24), 0x433C2C42U);
    ASSERT_EQ_HEX(sl[12] | (sl[13] << 8), 0x2256U);
    ASSERT_MEM_EQ(cb.table, table, sizeof(table));
}

TEST(cheat_cb_decrypt_matches_reference) {
    for (size_t i = 0; i < sizeof(k_cb) / sizeof(k_cb[0]); i++) {
        CbCrypt cb;
        cheat_cb_reseed(&cb, k_cb[i][0], (uint16_t)k_cb[i][1]);
        uint32_t a = k_cb[i][2];
        uint16_t v = (uint16_t)k_cb[i][3];
        cheat_cb_decrypt(&cb, &a, &v);
        ASSERT_EQ_HEX(a, k_cb[i][4]);
        ASSERT_EQ_HEX(v, k_cb[i][5]);
    }
}

void run_cheat_crypto_tests(void) {
    TEST_SUITE("cheat_crypto");
    RUN_TEST(cheat_tea_gsa_matches_reference);
    RUN_TEST(cheat_tea_par3_matches_reference);
    RUN_TEST(cheat_cb_reseed_matches_reference);
    RUN_TEST(cheat_cb_decrypt_matches_reference);
}
